local ServiceDescriptorImplementationTypeResolver = {}

function ServiceDescriptorImplementationTypeResolver.ResolveFromImplementationTypeWithArgs(
	serviceProvider: ServiceProvider,
	service,
	implementationType,
	serviceType,
	unsolved: { string },
	luaTypeProvider: ILuaTypeProvider,
	...
)
	local constructor, finalImplType, isConstraintError = ServiceDescriptorImplementationTypeResolver._getConstructor(
		service,
		implementationType,
		serviceType,
		luaTypeProvider
	)
	if isConstraintError then
		return nil
	end

	local args
	if constructor == nil then
		args = nil
	else
		args = { ... }
		local moreArgs = ServiceDescriptorImplementationTypeResolver._getArgs(
			implementationType,
			serviceType,
			serviceProvider,
			constructor,
			unsolved,
			#args
		)
		if moreArgs then
			for k, v in moreArgs do
				table.insert(args, v)
			end
		end

		if #args == 0 then
			args = nil
		end
	end

	if finalImplType.IsGenericTypeDefinition then
		-- 在Lua中处理泛型类型定义可能需要特殊处理
	end

	if not serviceType.IsGenericTypeDefinition then
		return ServiceDescriptorImplementationTypeResolver._createInstance(finalImplType, args)
	else
		return ServiceDescriptorImplementationTypeResolver._resolveGeneric(finalImplType, args)
	end
end

function ServiceDescriptorImplementationTypeResolver.ResolveFromImplementationType(
	serviceProvider: ServiceProvider,
	service,
	implementationType,
	serviceType,
	unsolved: { string },
	luaTypeProvider: ILuaTypeProvider
)
	return ServiceDescriptorImplementationTypeResolver.ResolveFromImplementationTypeWithArgs(
		serviceProvider,
		service,
		implementationType,
		serviceType,
		unsolved,
		luaTypeProvider
	)
end

function ServiceDescriptorImplementationTypeResolver._resolveGeneric(type, args)
	-- 在Lua中处理泛型可能需要特殊实现
	local configurationInstance = ServiceDescriptorImplementationTypeResolver._createInstance(type, args)
	return configurationInstance
end

function ServiceDescriptorImplementationTypeResolver._getArgs(
	implementationType,
	serviceType,
	serviceProvider: IServiceProvider,
	constructor,
	unsolved,
	trimArgsCount: number?
)
	local args = {}

	trimArgsCount = trimArgsCount or 0

	if constructor ~= nil then
		local constructorParams = constructor:GetParameters()

		for i = 1, #constructorParams do
			if i <= trimArgsCount then
				continue
			end

			local param = constructorParams[i]
			local success, resolved = pcall(function()
				unsolved = ServiceDescriptorImplementationTypeResolver._updateUnsolvedService(unsolved, serviceType)
				if ServiceDescriptorImplementationTypeResolver._contains(unsolved, param.ParameterType.FullName) then
					error({ type = "CircularDependencyException", Services = { param.ParameterType.FullName } })
				end

				local resolved = serviceProvider:GetServiceWithUnsolved(unsolved, param.ParameterType.FullName)

				if resolved == nil then
					error({
						type = "InvalidOperationException",
						message = string.format(
							"Unable to resolve service for type '%s' while attempting to activate '%s'",
							param.ParameterType.FullName,
							implementationType
						),
					})
				end

				ServiceDescriptorImplementationTypeResolver._remove(unsolved, serviceType)

				return resolved
			end)

			if not success then
				if resolved.type == "CircularDependencyException" then
					print(table.concat(unsolved, "\n"))
					table.insert(resolved.Services, serviceType)
					if unsolved[1] == serviceType then
						local sb = {}
						for i = #resolved.Services, 1, -1 do
							table.insert(sb, resolved.Services[i])
						end
						error(
							string.format(
								"A circular dependency was detected for the service of type '%s'.\n%s",
								resolved.Services[#resolved.Services],
								table.concat(sb, " -> ")
							)
						)
					end
				end
				warn("error on resolve service:", serviceType)
				if resolved.message then
					error(resolved.message, 0)
				else
					error(resolved, 0)
				end
			end

			table.insert(args, resolved)
		end
	end

	return args
end

function ServiceDescriptorImplementationTypeResolver._updateUnsolvedService(unsolved, service)
	if unsolved == nil then
		unsolved = {}
	end

	if not ServiceDescriptorImplementationTypeResolver._contains(unsolved, service) then
		table.insert(unsolved, service)
	end
	return unsolved
end

function ServiceDescriptorImplementationTypeResolver._getConstructor(
	service,
	implementationType,
	serviceType,
	luaTypeProvider: ILuaTypeProvider
)
	local implLuaType = luaTypeProvider.GetType(implementationType)
	if not implLuaType then
		error("Unable to resolve service for type '" .. implementationType .. "'")
	end
	local serviceType = luaTypeProvider.GetType(serviceType)
	local finalImplType = implLuaType
	local constructors = nil
	local isConstraintError = false

	if implLuaType.IsGenericType then
		local genericArgs = serviceType.GetGenericArguments()

		local tmp = genericArgs[1].GetGenericArguments()
		if #tmp > 0 then
			genericArgs = tmp
		end

		if implLuaType.IsGenericTypeDefinition then
			local success, genericType = pcall(function()
				return implLuaType.MakeGenericType(genericArgs)
			end)

			if not success then
				isConstraintError = true
				return nil, finalImplType, isConstraintError
			end

			finalImplType = genericType
			constructors = genericType:GetConstructors()
		else
			constructors = implLuaType:GetConstructors()
		end
	else
		constructors = implLuaType:GetConstructors()
	end

	if #constructors == 0 then
		constructors = implLuaType:GetConstructors()
	end

	local constructor = constructors[1]

	if finalImplType.IsGenericTypeDefinition then
		-- 在Lua中处理泛型类型定义可能需要特殊处理
	end

	return constructor, finalImplType, isConstraintError
end

function ServiceDescriptorImplementationTypeResolver._contains(tbl, item)
	for _, v in ipairs(tbl) do
		if v == item then
			return true
		end
	end
	return false
end

function ServiceDescriptorImplementationTypeResolver._remove(tbl, item)
	for i, v in ipairs(tbl) do
		if v == item then
			table.remove(tbl, i)
			break
		end
	end
end

function ServiceDescriptorImplementationTypeResolver._createInstance(type: LuaType, args)
	local constructor = type:GetConstructors()[1]
	if constructor and constructor.luaCtor then
		return constructor.luaCtor(unpack(args or {}))
	else
		error("Unable to create instance for type: " .. type.FullName)
	end
end

return ServiceDescriptorImplementationTypeResolver
